package safari;

import java.util.Map;

/**
 * Immutable configuration for one species.
 */
record SpeciesConfig(
    SpeciesType type,
    int breedingAge,
    int maxAge,
    double breedingProbability,
    int maxLitterSize,
    int maxTimeUntilBreedingAgain,
    int initialFoodLevel,
    int randomFoodUpperBound,
    double maxFoodLevel,
    double initialGrowthScale,
    double actGrowthIncrement,
    Map<Weather, Double> foodFindingProbabilities,
    Map<ActorKind, Integer> food
)
{
    SpeciesConfig
    {
        foodFindingProbabilities = Map.copyOf(foodFindingProbabilities);
        food = Map.copyOf(food);
    }

    double foodFindingProbability(Weather weather)
    {
        return foodFindingProbabilities.getOrDefault(weather, 0.0);
    }
}

package safari;

import java.util.Arrays;
import java.util.List;
import java.util.Properties;
import java.util.Random;

/**
 * Central registry for population seeding rules.
 */
final class SpawnRegistry
{
    private static final List<SpawnRule> RULES = loadRules();

    private SpawnRegistry()
    {
    }

    static Actor seedActor(Field field, int row, int col, Random random)
    {
        Location location = new Location(row, col);
        for(SpawnRule rule : RULES) {
            if(random.nextDouble() <= rule.probability()) {
                return createActor(rule.kind(), field, location);
            }
        }
        return null;
    }

    private static List<SpawnRule> loadRules()
    {
        Properties properties = ConfigLoader.loadProperties("config/spawn.properties");
        String orderValue = ConfigLoader.requiredString(properties, "spawn.order");
        return Arrays.stream(orderValue.split(","))
            .map(String::trim)
            .filter(value -> !value.isEmpty())
            .map(value -> new SpawnRule(
                ActorKind.valueOf(value),
                ConfigLoader.requiredDouble(properties, "spawn." + value)
            ))
            .toList();
    }

    private static Actor createActor(ActorKind kind, Field field, Location location)
    {
        return switch(kind) {
            case GAZELLE -> SpeciesRegistry.create(SpeciesType.GAZELLE, true, field, location);
            case ZEBRA -> SpeciesRegistry.create(SpeciesType.ZEBRA, true, field, location);
            case CHEETAH -> SpeciesRegistry.create(SpeciesType.CHEETAH, true, field, location);
            case LION -> SpeciesRegistry.create(SpeciesType.LION, true, field, location);
            case JAGUAR -> SpeciesRegistry.create(SpeciesType.JAGUAR, true, field, location);
            case GRASS -> new Grass(true, field, location);
            case HUNTER -> new Hunter(field, location);
        };
    }
}

package safari;

import java.util.EnumMap;
import java.util.Properties;
import java.util.Map;

/**
 * Central registry for immutable species configuration and construction.
 */
final class SpeciesRegistry
{
    private static final Map<SpeciesType, SpeciesConfig> CONFIGS = loadConfigs();
    }

    private SpeciesRegistry()
    {
    }

    static SpeciesConfig config(SpeciesType type)
    {
        SpeciesConfig config = CONFIGS.get(type);
        if(config == null) {
            throw new IllegalArgumentException("Unknown species type: " + type);
        }
        return config;
    }

    static Animal create(SpeciesType type, boolean randomAge, Field field, Location location)
    {
        return new Animal(type, randomAge, field, location);
    }

    private static Map<SpeciesType, SpeciesConfig> loadConfigs()
    {
        Properties properties = ConfigLoader.loadProperties("config/species.properties");
        Map<SpeciesType, SpeciesConfig> configs = new EnumMap<>(SpeciesType.class);
        for(SpeciesType type : SpeciesType.values()) {
            String prefix = "species." + type.name() + ".";
            configs.put(
                type,
                new SpeciesConfig(
                    type,
                    ConfigLoader.requiredInt(properties, prefix + "breedingAge"),
                    ConfigLoader.requiredInt(properties, prefix + "maxAge"),
                    ConfigLoader.requiredDouble(properties, prefix + "breedingProbability"),
                    ConfigLoader.requiredInt(properties, prefix + "maxLitterSize"),
                    ConfigLoader.requiredInt(properties, prefix + "maxTimeUntilBreedingAgain"),
                    ConfigLoader.requiredInt(properties, prefix + "initialFoodLevel"),
                    ConfigLoader.requiredInt(properties, prefix + "randomFoodUpperBound"),
                    ConfigLoader.requiredDouble(properties, prefix + "maxFoodLevel"),
                    ConfigLoader.requiredDouble(properties, prefix + "initialGrowthScale"),
                    ConfigLoader.requiredDouble(properties, prefix + "actGrowthIncrement"),
                    ConfigLoader.requiredWeatherMap(properties, prefix + "foodFinding."),
                    ConfigLoader.requiredActorKindMap(properties, prefix + "food.")
                )
            );
        }
        return configs;
    }
}
